CREATE TABLE weighings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE DEFAULT('WGH-'||gen_random_uuid()::text),project_id uuid NOT NULL REFERENCES projects(id),customer_id uuid NOT NULL REFERENCES customers(id),kind text NOT NULL CHECK(kind IN('BUNDLE','VEHICLE')),vehicle_no text NOT NULL DEFAULT '',loading_id uuid,gross_weight numeric(14,6) NOT NULL CHECK(gross_weight>0),tare_weight numeric(14,6) NOT NULL CHECK(tare_weight>=0 AND tare_weight<gross_weight),net_weight numeric(14,6) GENERATED ALWAYS AS(gross_weight-tare_weight) STORED,bundle_weight numeric(14,6) NOT NULL DEFAULT 0,difference numeric(14,6) GENERATED ALWAYS AS(gross_weight-tare_weight-bundle_weight) STORED,scale_no text NOT NULL CHECK(length(trim(scale_no)) BETWEEN 1 AND 80),weighed_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','RECORDED','VOID')),void_reason text,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,FOREIGN KEY(project_id,customer_id) REFERENCES customers(project_id,id),CHECK(kind<>'VEHICLE' OR length(trim(vehicle_no))>0));
CREATE TABLE weighing_items(weighing_id uuid NOT NULL REFERENCES weighings(id),bundle_id uuid NOT NULL REFERENCES bundles(id),original_weight numeric(14,6) NOT NULL CHECK(original_weight>0),PRIMARY KEY(weighing_id,bundle_id));
CREATE TRIGGER weighing_state BEFORE UPDATE OR DELETE ON weighings FOR EACH ROW EXECUTE FUNCTION v23_state_owner();
CREATE TRIGGER weighing_items_history BEFORE UPDATE OR DELETE ON weighing_items FOR EACH ROW EXECUTE FUNCTION v23_immutable();
CREATE FUNCTION weighing_action(actor uuid,doc uuid,expected int,action text,reason text DEFAULT '') RETURNS weighings LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d weighings;b bundles;w uuid;BEGIN
 SELECT * INTO d FROM weighings WHERE id=doc FOR UPDATE;
 IF NOT FOUND OR d.version<>expected OR NOT((action='record' AND d.status='DRAFT') OR(action='void' AND d.status='RECORDED' AND length(trim(reason)) BETWEEN 1 AND 500)) THEN RAISE EXCEPTION 'Invalid weighing transition or version' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM weighing_items WHERE weighing_id=doc) OR(d.kind='BUNDLE' AND(SELECT count(*) FROM weighing_items WHERE weighing_id=doc)<>1) THEN RAISE EXCEPTION 'Invalid weighing bundle count' USING ERRCODE='23514';END IF;
 FOR b IN SELECT x.* FROM bundles x JOIN weighing_items i ON i.bundle_id=x.id WHERE i.weighing_id=doc ORDER BY x.id FOR UPDATE OF x LOOP
 SELECT warehouse_id INTO w FROM locations WHERE id=b.location_id;PERFORM v23_require(actor,'weigh:write',d.project_id,d.customer_id,w);
 IF b.project_id<>d.project_id OR(action='record' AND(b.physical_status<>'IN_STOCK' OR NOT EXISTS(SELECT 1 FROM weighing_items WHERE weighing_id=doc AND bundle_id=b.id AND original_weight=b.net_weight))) THEN RAISE EXCEPTION 'Weighing bundle changed or unavailable' USING ERRCODE='23514';END IF;END LOOP;
 UPDATE weighings SET status=CASE action WHEN 'record' THEN 'RECORDED' ELSE 'VOID' END,bundle_weight=(SELECT sum(original_weight) FROM weighing_items WHERE weighing_id=doc),void_reason=CASE WHEN action='void' THEN reason ELSE NULL END,version=version+1 WHERE id=doc RETURNING * INTO d;
 FOR b IN SELECT x.* FROM bundles x JOIN weighing_items i ON i.bundle_id=x.id WHERE i.weighing_id=doc LOOP INSERT INTO inventory_events(bundle_id,event_type,physical_delta,actor_id,after_data) VALUES(b.id,'WEIGH',0,actor,jsonb_build_object('weighing_id',doc,'code',d.code,'net_weight',d.net_weight::text,'difference',d.difference::text,'status',d.status));END LOOP;
 INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'weighing_'||action,'weighings',doc::text,to_jsonb(d));RETURN d;END $$;
REVOKE ALL ON FUNCTION weighing_action(uuid,uuid,int,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION weighing_action(uuid,uuid,int,text,text) TO musonoi_app;
GRANT SELECT,INSERT ON weighings,weighing_items TO musonoi_app;
